#include "elit21/aliexpress/auth/AliExpressOAuthClient.h"
#include "elit21/aliexpress/AliExpressEndpoints.h"
#include "elit21/json/Json.h"
namespace elit21::aliexpress::auth {Result<AliExpressToken>AliExpressOAuthClient::parse(const HttpResponse&r){if(r.status<200||r.status>=300)return Result<AliExpressToken>::failure("AliExpress OAuth HTTP "+std::to_string(r.status)+": "+r.body);auto j=Json::parse(r.body);if(!j)return Result<AliExpressToken>::failure(j.error());auto x=j.value();if(x.contains("error"))return Result<AliExpressToken>::failure(x.dump());AliExpressToken t;t.access_token=x.getString("access_token");t.refresh_token=x.getString("refresh_token");t.account_id=x.getString("user_id",x.getString("account_id"));t.expires_in_seconds=static_cast<long long>(x.getNumber("expires_in",0));t.refresh_expires_in_seconds=static_cast<long long>(x.getNumber("refresh_expires_in",0));return t.valid()?Result<AliExpressToken>::success(t):Result<AliExpressToken>::failure("AliExpress OAuth response is incomplete");}Result<AliExpressToken>AliExpressOAuthClient::createToken(const std::string&k,const std::string&s,const std::string&c){if(k.empty()||s.empty()||c.empty())return Result<AliExpressToken>::failure("AliExpress token parameters are incomplete");auto r=http_.postForm(AliExpressEndpoints::tokenCreate(),{{"client_id",k},{"client_secret",s},{"code",c},{"grant_type","authorization_code"}});return r?parse(r.value()):Result<AliExpressToken>::failure(r.error());}Result<AliExpressToken>AliExpressOAuthClient::refreshToken(const std::string&k,const std::string&s,const std::string&t){if(k.empty()||s.empty()||t.empty())return Result<AliExpressToken>::failure("AliExpress refresh parameters are incomplete");auto r=http_.postForm(AliExpressEndpoints::tokenRefresh(),{{"client_id",k},{"client_secret",s},{"refresh_token",t},{"grant_type","refresh_token"}});return r?parse(r.value()):Result<AliExpressToken>::failure(r.error());}}
